#include <iostream>
#include <string>
#include <stack>
using namespace std;

int main() {
    int t;
    cin >> t;
    while (t--) {
        string s;
        cin >> s;
        stack<char> st;
        bool ok = true;
        for (char c : s) {
            if (c == '(' || c == '[' || c == '{') {
                st.push(c);
            } else {
                char want = (c == ')') ? '(' : (c == ']') ? '[' : '{';
                if (st.empty() || st.top() != want) { ok = false; break; }
                st.pop();
            }
        }
        cout << (ok && st.empty() ? "YES" : "NO") << "\n";
    }
    return 0;
}

