cnt = Counter(a)
vals = sorted(cnt)
count = 0
for i, x in enumerate(vals):
    if x > 0:
        break
    for y in vals[i:]:
        z = -x - y
        if z < y:
            break
        if z not in cnt:
            continue
        need = Counter((x, y, z))
        if all(cnt[v] >= k for v, k in need.items()):
            count += 1
print(count)

