#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int n, T;
vector<int> v;

long long go(int start, int remaining) {
    if (remaining == 0) return 1;
    long long total = 0;
    for (int i = start; i < n; i++) {
        if (v[i] > remaining) break;
        if (i > start && v[i] == v[i - 1]) continue;
        total += go(i + 1, remaining - v[i]);
    }
    return total;
}

int main() {
    cin >> n >> T;
    v.resize(n);
    for (auto &x : v) cin >> x;
    sort(v.begin(), v.end());
    cout << go(0, T) << "\n";
    return 0;
}

