int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<pair<int,int>>> adj(n + 1);
    vector<pair<int,int>> ends(m);
    for (int i = 0; i < m; i++) {
        int a, b;
        cin >> a >> b;
        adj[a].push_back({b, i});
        adj[b].push_back({a, i});
        ends[i] = {min(a, b), max(a, b)};
    }
    vector<int> tin(n + 1, -1), low(n + 1, 0), pedge(n + 1, -1), it(n + 1, 0), stack;
    vector<pair<int,int>> bridges;
    int timer = 0;
    for (int s = 1; s <= n; s++) {
        if (tin[s] != -1) continue;
        tin[s] = low[s] = timer++;
        stack.push_back(s);
        while (!stack.empty()) {
            int u = stack.back();
            if (it[u] < (int)adj[u].size()) {
                auto [v, eid] = adj[u][it[u]++];
                if (eid == pedge[u]) continue;
                if (tin[v] == -1) {
                    pedge[v] = eid;
                    tin[v] = low[v] = timer++;
                    stack.push_back(v);
                } else {
                    low[u] = min(low[u], tin[v]);
                }
            } else {
                stack.pop_back();
                if (!stack.empty()) {
                    int p = stack.back();
                    low[p] = min(low[p], low[u]);
                    if (low[u] > tin[p]) bridges.push_back(ends[pedge[u]]);
                }
            }
        }
    }
    sort(bridges.begin(), bridges.end());
    cout << bridges.size() << "\n";
    for (auto [a, b] : bridges) cout << a << " " << b << "\n";
    return 0;
