#include <iostream>
#include <vector>
#include <utility>
#include <algorithm>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<int>> adj(n + 1), radj(n + 1);
    vector<pair<int,int>> edges(m);
    for (int i = 0; i < m; i++) {
        int a, b;
        cin >> a >> b;
        adj[a].push_back(b);
        radj[b].push_back(a);
        edges[i] = {a, b};
    }
    vector<int> it(n + 1, 0), order, stack;
    vector<bool> seen(n + 1, false);
    for (int s = 1; s <= n; s++) {
        if (seen[s]) continue;
        seen[s] = true;
        stack.push_back(s);
        while (!stack.empty()) {
            int u = stack.back();
            if (it[u] < (int)adj[u].size()) {
                int v = adj[u][it[u]++];
                if (!seen[v]) { seen[v] = true; stack.push_back(v); }
            } else {
                stack.pop_back();
                order.push_back(u);
            }
        }
    }
    vector<int> comp(n + 1, -1);
    int c = 0;
    for (int i = n - 1; i >= 0; i--) {
        int s = order[i];
        if (comp[s] != -1) continue;
        comp[s] = c;
        stack.push_back(s);
        while (!stack.empty()) {
            int u = stack.back(); stack.pop_back();
            for (int v : radj[u]) if (comp[v] == -1) { comp[v] = c; stack.push_back(v); }
        }
        c++;
    }
    if (c == 1) { cout << 0 << "\n"; return 0; }
    vector<bool> hasIn(c, false), hasOut(c, false);
    for (auto [a, b] : edges)
        if (comp[a] != comp[b]) { hasOut[comp[a]] = true; hasIn[comp[b]] = true; }
    int sources = 0, sinks = 0;
    for (int i = 0; i < c; i++) { sources += !hasIn[i]; sinks += !hasOut[i]; }
    cout << max(sources, sinks) << "\n";
    return 0;
}

