#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

typedef unsigned long long ull;
const ull MOD = (1ULL << 61) - 1;

ull mulmod(ull a, ull b) {
    unsigned __int128 p = (unsigned __int128)a * b;
    ull lo = (ull)(p & MOD), hi = (ull)(p >> 61);
    ull r = lo + hi;
    if (r >= MOD) r -= MOD;
    return r;
}

int main() {
    string s;
    cin >> s;
    int n = s.size();
    const ull B = 911382323ULL;
    vector<ull> h(n + 1, 0), pw(n + 1, 1);
    for (int i = 0; i < n; i++) {
        h[i + 1] = (mulmod(h[i], B) + (ull)(s[i] - 'a' + 1)) % MOD;
        pw[i + 1] = mulmod(pw[i], B);
    }
    long long total = 0;
    vector<ull> v;
    for (int L = 1; L <= n; L++) {
        v.clear();
        for (int i = 0; i + L <= n; i++) {
            ull x = (h[i + L] + MOD - mulmod(h[i], pw[L])) % MOD;
            v.push_back(x);
        }
        sort(v.begin(), v.end());
        total += unique(v.begin(), v.end()) - v.begin();
    }
    cout << total << "\n";
    return 0;
}

