Mat mul(const Mat &A, const Mat &B) {
    Mat C{};
    for (int i = 0; i < 2; i++)
        for (int j = 0; j < 2; j++)
            C[i][j] = (A[i][0] * B[0][j] % MOD + A[i][1] * B[1][j] % MOD) % MOD;
